return ['domain'=>'hourspilot','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar','project-id-version'=>'HoursPilot 0.2.0','pot-creation-date'=>'2026-10-29T20:56:54+00:00','po-revision-date'=>'2026-10-29 22:00+0100','x-generator'=>'WP-CLI 2.12.0','messages'=>['HoursPilot'=>'HoursPilot','https://github.com/TSA3000/hourspilot'=>'https://github.com/TSA3000/hourspilot','Business hours, holidays and live open/closed status for one or more locations. Shortcode, cache-friendly, schema.org markup.'=>'ساعات العمل والعطلات وحالة مفتوح/مغلق المباشرة لموقع واحد أو أكثر. رمز قصير، متوافق مع التخزين المؤقت، وبيانات schema.org المنظمة.','Arthur Sam Mahdi'=>'Arthur Sam Mahdi','https://github.com/TSA3000'=>'https://github.com/TSA3000','Holidays and special hours'=>'العطلات والساعات الخاصة','Location details'=>'تفاصيل الموقع','Shortcode'=>'الرمز القصير','Open'=>'مفتوح','Closed'=>'مغلق','Open 24 hours'=>'مفتوح على مدار الساعة','Add hours'=>'إضافة ساعات','Copy Monday to Tuesday–Friday'=>'نسخ الإثنين إلى الثلاثاء–الجمعة','Add several hours per day for lunch breaks. A closing time earlier than the opening time runs past midnight (e.g. 22:00–02:00).'=>'أضف عدة فترات في اليوم لاستراحة الغداء. وقت الإغلاق الأسبق من وقت الفتح يمتد إلى ما بعد منتصف الليل (مثل 22:00–02:00).','Opens'=>'يفتح','Closes'=>'يغلق','Remove hours'=>'إزالة الساعات','From'=>'من','To (optional)'=>'إلى (اختياري)','Name'=>'الاسم','Hours (empty = closed)'=>'الساعات (فارغ = مغلق)','Every year'=>'كل سنة','Remove'=>'إزالة','Add holiday or special day'=>'إضافة عطلة أو يوم خاص','Special hours format: 10:00-14:00. Separate several with commas. Past holidays are hidden automatically on the site. Every year: the same dates repeat each year (the year you enter is ignored).'=>'صيغة الساعات الخاصة: 10:00-14:00. افصل بين عدة فترات بفواصل. تُخفى العطلات الماضية تلقائيًا على الموقع. كل سنة: تتكرر التواريخ نفسها كل سنة (يتم تجاهل السنة التي تدخلها).','e.g. Christmas Eve'=>'مثلًا: عيد الفطر','Remove row'=>'إزالة الصف','Time zone'=>'المنطقة الزمنية','Your site uses a UTC offset, which ignores daylight saving time. Pick a city here so the open/closed status stays correct all year.'=>'يستخدم موقعك فارق توقيت UTC ثابتًا لا يراعي التوقيت الصيفي. اختر مدينة هنا لتبقى حالة مفتوح/مغلق صحيحة طوال السنة.','Business type'=>'نوع النشاط التجاري','Used in the structured data search engines read.'=>'يُستخدم في البيانات المنظمة التي تقرؤها محركات البحث.','Phone'=>'الهاتف','Email'=>'البريد الإلكتروني','Website'=>'الموقع الإلكتروني','Address'=>'العنوان','Map link'=>'رابط الخريطة','Set the location image with "Location image" in the sidebar.'=>'عيّن صورة الموقع من «صورة الموقع» في الشريط الجانبي.','Save the location to get its shortcode.'=>'احفظ الموقع للحصول على الرمز القصير الخاص به.','Business hours'=>'ساعات العمل','Location'=>'موقع','Locations'=>'المواقع','Add location'=>'إضافة موقع','Edit location'=>'تعديل الموقع','Search locations'=>'البحث في المواقع','No locations yet. Add one to start showing hours.'=>'لا توجد مواقع بعد. أضف موقعًا لبدء عرض ساعات العمل.','Location image'=>'صورة الموقع','Set location image'=>'تعيين صورة الموقع','Opening in [time]'=>'يفتح بعد [time]','Closing in [time]'=>'يغلق بعد [time]','Open now'=>'مفتوح الآن','Closed now'=>'مغلق الآن','HoursPilot: location not found or not published. Check the id in the shortcode.'=>'HoursPilot: لم يتم العثور على الموقع أو أنه غير منشور. تحقق من المعرّف (id) في الرمز القصير.','closes %s'=>'يغلق %s','opens %s'=>'يفتح %s','Today'=>'اليوم','tomorrow'=>'غدًا','Previous month'=>'الشهر السابق','Next month'=>'الشهر التالي','list separator, '=>'، ','Get directions'=>'الحصول على الاتجاهات','Appearance'=>'المظهر','Label: optional text shown next to the hours, e.g. "Lunch". Break: the hours are shown but count as closed.'=>'التسمية: نص اختياري يظهر بجانب الساعات، مثل «استراحة الغداء». استراحة: تظهر الساعات لكنها تُحسب مغلقة.','Label (optional)'=>'تسمية (اختياري)','Label'=>'التسمية','Break'=>'استراحة','Second phone'=>'هاتف ثانٍ','Map position'=>'موقع الخريطة','Latitude, longitude for the embedded map (needed for OpenStreetMap; Google Maps can use the address instead).'=>'خط العرض، خط الطول للخريطة المضمّنة (مطلوب لـ OpenStreetMap؛ يمكن لخرائط Google استخدام العنوان بدلًا من ذلك).','Style'=>'النمط','Clean (default)'=>'بسيط (افتراضي)','Card with header band'=>'بطاقة بشريط علوي','Accent colour'=>'لون التمييز','Header band'=>'الشريط العلوي','Green when open, red when closed'=>'أخضر عند الفتح، أحمر عند الإغلاق','Own colour (below)'=>'لون مخصص (أدناه)','Header band colour'=>'لون الشريط العلوي','Card style only.'=>'لنمط البطاقة فقط.','Header image'=>'صورة الشريط العلوي','Font'=>'الخط','Theme font'=>'خط القالب','Monospace'=>'خط ثابت العرض','Map'=>'الخريطة','None'=>'بدون','OpenStreetMap'=>'OpenStreetMap','Google Maps'=>'خرائط Google','header date formatl F jS'=>'l j F','Current local time is'=>'الوقت المحلي الآن','Map (%s)'=>'الخريطة (%s)','Show map'=>'عرض الخريطة','Loads the map from %s.'=>'يحمّل الخريطة من %s.','Shared holidays'=>'العطلات المشتركة','Import / Export'=>'استيراد / تصدير','Location settings'=>'إعدادات الموقع','General'=>'عام','Hours'=>'الساعات','Holidays'=>'العطلات','Messages'=>'الرسائل','Display'=>'العرض','Empty fields use the default shown in grey. Shortcode attributes override these settings.'=>'الحقول الفارغة تستخدم القيمة الافتراضية الظاهرة باللون الرمادي. خصائص الرمز القصير تتقدّم على هذه الإعدادات.','Language'=>'اللغة','Day and month names follow the site language (Settings → General). With Polylang or WPML they follow the page language.'=>'تتبع أسماء الأيام والأشهر لغة الموقع (الإعدادات ← عام). مع Polylang أو WPML تتبع لغة الصفحة.','Also use the %d shared holiday'=>'استخدم أيضًا العطلات المشتركة (%d)' . "\0" . 'استخدم أيضًا العطلات المشتركة (%d)' . "\0" . 'استخدم أيضًا العطلات المشتركة (%d)' . "\0" . 'استخدم أيضًا العطلات المشتركة (%d)' . "\0" . 'استخدم أيضًا العطلات المشتركة (%d)' . "\0" . 'استخدم أيضًا العطلات المشتركة (%d)','Edit shared holidays'=>'تعديل العطلات المشتركة','Paste into any page, widget or page-builder shortcode block. It uses the settings in the tabs; attributes override them, e.g.:'=>'الصقه في أي صفحة أو ودجت أو كتلة رمز قصير. يستخدم إعدادات التبويبات، وتتقدّم عليها الخصائص، مثلًا:','Holidays every location uses, e.g. public holidays. A location can opt out in its Holidays tab and add its own.'=>'عطلات تستخدمها جميع المواقع، مثل العطلات الرسمية. يمكن للموقع إلغاء استخدامها من تبويب العطلات وإضافة عطلاته الخاصة.','Save shared holidays'=>'حفظ العطلات المشتركة','Sorry, you are not allowed to do that.'=>'عذرًا، غير مسموح لك بذلك.','Export'=>'تصدير','Download all locations (hours, holidays, details, settings) and the shared holidays as a JSON file. Images are not included.'=>'نزّل جميع المواقع (الساعات، العطلات، التفاصيل، الإعدادات) والعطلات المشتركة كملف JSON. الصور غير مضمّنة.','To export one location, use "Export" below its name in the Locations list.'=>'لتصدير موقع واحد، استخدم «تصدير» أسفل اسمه في قائمة المواقع.','Export all locations'=>'تصدير جميع المواقع','Import'=>'استيراد','Import a HoursPilot JSON file. Each location is added as a new draft, so you can check it before publishing.'=>'استورد ملف JSON من HoursPilot. يُضاف كل موقع كمسودة جديدة لتتمكن من مراجعته قبل النشر.','Also replace the shared holidays with the ones in the file'=>'استبدل أيضًا العطلات المشتركة بالعطلات الموجودة في الملف','Imported location'=>'موقع مستورد','Shared holidays saved.'=>'تم حفظ العطلات المشتركة.','%d location imported as a draft.'=>'تم استيراد مواقع كمسودات: %d' . "\0" . 'تم استيراد مواقع كمسودات: %d' . "\0" . 'تم استيراد مواقع كمسودات: %d' . "\0" . 'تم استيراد مواقع كمسودات: %d' . "\0" . 'تم استيراد مواقع كمسودات: %d' . "\0" . 'تم استيراد مواقع كمسودات: %d','That file is not a HoursPilot export.'=>'هذا الملف ليس تصديرًا من HoursPilot.','Open message'=>'رسالة الفتح','Card style: line in the header while open, e.g. "We are open! Come in."'=>'نمط البطاقة: سطر في الشريط العلوي أثناء الفتح، مثل «نحن مفتوحون، تفضّلوا!»','Closed message'=>'رسالة الإغلاق','Card style: line in the header while closed.'=>'نمط البطاقة: سطر في الشريط العلوي أثناء الإغلاق.','Open badge'=>'شارة الفتح','Card style: the short status label.'=>'نمط البطاقة: تسمية الحالة القصيرة.','Closed badge'=>'شارة الإغلاق','Status while open'=>'الحالة أثناء الفتح','Followed by the closing time, e.g. "Open now, closes 17:00".'=>'يليها وقت الإغلاق، مثل «مفتوح الآن، يغلق 17:00».','Status while closed'=>'الحالة أثناء الإغلاق','Followed by the next opening.'=>'يليها موعد الفتح التالي.','Closed all day'=>'مغلق طوال اليوم','Shown for closed days, e.g. "Closed All Day".'=>'يظهر للأيام المغلقة، مثل «مغلق طوال اليوم».','Local time text'=>'نص الوقت المحلي','Card style: text before the local time.'=>'نمط البطاقة: نص قبل الوقت المحلي.','Holidays title'=>'عنوان العطلات','Opening countdown'=>'العد التنازلي للفتح','[time] is replaced by the countdown.'=>'يُستبدل [time] بالعد التنازلي.','Closing countdown'=>'العد التنازلي للإغلاق','Layout'=>'التخطيط','Days'=>'الأيام','Whole week'=>'الأسبوع كاملًا','Only today'=>'اليوم فقط','Vertical list'=>'قائمة عمودية','Horizontal: one card per day'=>'أفقي: بطاقة لكل يوم','Calendar month'=>'شهر في التقويم','Header'=>'الترويسة','Show the header (title or date, status, local time)'=>'إظهار الترويسة (العنوان أو التاريخ، الحالة، الوقت المحلي)','Status badge'=>'شارة الحالة','Show whether the location is open now'=>'إظهار ما إذا كان الموقع مفتوحًا الآن','Local time'=>'الوقت المحلي','Show the current time at the location in the header'=>'إظهار الوقت الحالي في الموقع داخل الترويسة','Short day names'=>'أسماء أيام مختصرة','Mon, Tue … instead of Monday, Tuesday …'=>'إث، ثلا … بدلًا من الإثنين، الثلاثاء …','Group days'=>'تجميع الأيام','Merge consecutive days with the same hours (Mon – Fri)'=>'دمج الأيام المتتالية ذات الساعات نفسها (الإثنين – الجمعة)','Hide closed days'=>'إخفاء الأيام المغلقة','Hide days'=>'إخفاء أيام','For example tick Saturday and Sunday to hide the weekend.'=>'مثلًا حدّد السبت والأحد لإخفاء عطلة نهاية الأسبوع.','Upcoming holidays'=>'العطلات القادمة','List holidays and special hours'=>'عرض العطلات والساعات الخاصة','Holidays ahead (days)'=>'العطلات المقبلة (أيام)','How far ahead to list holidays.'=>'إلى أي مدى تُعرض العطلات القادمة.','Holidays position'=>'موضع العطلات','After the regular hours'=>'بعد الساعات المعتادة','Before the regular hours'=>'قبل الساعات المعتادة','Holiday hours in the week'=>'ساعات العطلات في الأسبوع','Show holiday hours instead of this week\'s regular hours (turns off grouping)'=>'إظهار ساعات العطلات بدلًا من الساعات المعتادة لهذا الأسبوع (يوقف التجميع)','Hide regular hours on holidays'=>'إخفاء الساعات المعتادة في العطلات','Only the holiday notice while today is a holiday'=>'إشعار العطلة فقط عندما يكون اليوم عطلة','Countdowns'=>'العد التنازلي','Count down to the next opening while closed'=>'العد التنازلي حتى الفتح التالي أثناء الإغلاق','Count down to closing'=>'العد التنازلي حتى الإغلاق','Closing countdown starts'=>'بدء العد التنازلي للإغلاق','Minutes before closing.'=>'دقائق قبل الإغلاق.','Countdown format'=>'صيغة العد التنازلي','Tokens {d} {h} {hh} {m} {mm} {s} {ss}. Without {d} hours keep counting past 24.'=>'الرموز {d} {h} {hh} {m} {mm} {s} {ss}. بدون {d} تستمر الساعات بعد 24.','Formats'=>'الصيغ','Time format'=>'صيغة الوقت','Empty = Settings → General. H:i = 24 hours, g:i A = 12 hours.'=>'فارغ = الإعدادات ← عام. ‎H:i = ‏24 ساعة، ‎g:i A = ‏12 ساعة.','Holiday date format'=>'صيغة تاريخ العطلات','PHP date format, e.g. j M or d/m.'=>'صيغة تاريخ PHP، مثل j M أو d/m.','Header date format'=>'صيغة التاريخ في الترويسة','Card style. PHP date format, e.g. l F jS = Monday November 29th.'=>'نمط البطاقة. صيغة تاريخ PHP، مثل l j F = الإثنين 29 نوفمبر.','Digits'=>'الأرقام','Western (0–9)'=>'غربية (0–9)','Arabic-Indic (٠–٩)'=>'هندية عربية (٠–٩)','Location and search engines'=>'الموقع ومحركات البحث','Show address, phone, email, website'=>'إظهار العنوان والهاتف والبريد الإلكتروني والموقع','Show the location image'=>'إظهار صورة الموقع','Structured data'=>'البيانات المنظمة','Add schema.org opening hours for search engines'=>'إضافة ساعات العمل بصيغة schema.org لمحركات البحث','Links, today marker, header band. Empty = teal.'=>'الروابط، علامة اليوم، الشريط العلوي. فارغ = أزرق مخضرّ.','Card style: image behind the header band, darkened so the text stays readable.'=>'نمط البطاقة: صورة خلف الشريط العلوي، معتّمة ليبقى النص مقروءًا.','Shown below the location details. OpenStreetMap needs the map position (Location tab).'=>'تظهر أسفل تفاصيل الموقع. يتطلب OpenStreetMap موقع الخريطة (تبويب الموقع).','Map privacy'=>'خصوصية الخريطة','Load the map only after a click (nothing is sent to the map service before)'=>'تحميل الخريطة بعد النقر فقط (لا يُرسل شيء إلى خدمة الخرائط قبل ذلك)','Choose image'=>'اختيار صورة','Closed on public holidays'=>'مغلق في العطلات الرسمية','Source'=>'المصدر','Country'=>'الدولة','— Choose —'=>'— اختر —','%s couldn\'t be reached; enter a two-letter country code.'=>'تعذّر الوصول إلى %s؛ أدخل رمز الدولة المكوّن من حرفين.','Nationwide public holidays from %s, checked weekly. To open on one of them, add that day above with its hours.'=>'العطلات الرسمية على مستوى الدولة من %s، تُحدَّث أسبوعيًا. لتفتح في إحداها، أضف ذلك اليوم أعلاه مع ساعاته.','No public holidays found for this country.'=>'لم يُعثر على عطلات رسمية لهذه الدولة.','Next public holidays:'=>'العطلات الرسمية القادمة:']];